(()=>{'use strict';if(window.__OBRIX_CONFIG_CLARO_PERIGO_3010)return;window.__OBRIX_CONFIG_CLARO_PERIGO_3010=true;
const norm=s=>String(s||'').replace(/\s+/g,' ').trim().toLowerCase();
function aplicar(){if(document.documentElement.dataset.theme!=='light')return;const root=document.getElementById('configMain');if(!root)return;root.querySelectorAll('button,.btn,[role="button"]').forEach(b=>{const t=norm(b.textContent);if(t!=='apagar equipe'&&t!=='apagar financeiro')return;b.style.setProperty('background','#f8fafc','important');b.style.setProperty('background-color','#f8fafc','important');b.style.setProperty('background-image','none','important');b.style.setProperty('color','#dc2626','important');b.style.setProperty('-webkit-text-fill-color','#dc2626','important');b.style.setProperty('border','2px solid #dc2626','important');b.style.setProperty('box-shadow','none','important');b.querySelectorAll('*').forEach(e=>{e.style.setProperty('color','#dc2626','important');e.style.setProperty('-webkit-text-fill-color','#dc2626','important')})})}
let t=0;const agendar=()=>{clearTimeout(t);t=setTimeout(aplicar,80)};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',agendar,{once:true});else agendar();document.addEventListener('click',agendar,true);window.addEventListener('obrix:theme-applied',agendar);new MutationObserver(m=>{if(m.some(x=>[...x.addedNodes].some(n=>n.nodeType===1&&(n.id==='configMain'||n.querySelector?.('#configMain')))))agendar()}).observe(document.body,{childList:true,subtree:true});new MutationObserver(agendar).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});window.OBRIX_CONFIG_CLARO_PERIGO_3010={refresh:aplicar};})();